class Solution {
  public long maxArea(int[][] coords) {
    int MAX = 1_000_001;
    int[] minXofY = new int[MAX],
        maxXofY = new int[MAX],
        minYofX = new int[MAX],
        maxYofX = new int[MAX];
    java.util.Arrays.fill(minXofY, Integer.MAX_VALUE);
    java.util.Arrays.fill(minYofX, Integer.MAX_VALUE);
    int minX = Integer.MAX_VALUE, maxX = 0, minY = Integer.MAX_VALUE, maxY = 0;
    for (int[] c : coords) {
      int x = c[0], y = c[1];
      minXofY[y] = Math.min(minXofY[y], x);
      maxXofY[y] = Math.max(maxXofY[y], x);
      minYofX[x] = Math.min(minYofX[x], y);
      maxYofX[x] = Math.max(maxYofX[x], y);
      minX = Math.min(minX, x);
      maxX = Math.max(maxX, x);
      minY = Math.min(minY, y);
      maxY = Math.max(maxY, y);
    }
    long best = -1;
    for (int y = 1; y < MAX; y++) {
      if (minXofY[y] == Integer.MAX_VALUE || maxXofY[y] == minXofY[y]) continue;
      long base = maxXofY[y] - minXofY[y], h = Math.max(y - minY, maxY - y);
      if (h > 0) best = Math.max(best, base * h);
    }
    for (int x = 1; x < MAX; x++) {
      if (minYofX[x] == Integer.MAX_VALUE || maxYofX[x] == minYofX[x]) continue;
      long base = maxYofX[x] - minYofX[x], h = Math.max(x - minX, maxX - x);
      if (h > 0) best = Math.max(best, base * h);
    }
    return best;
  }
}
